/**
 * Carte de livraison — trame de points et villes desservies.
 *
 * Le tracé et les coordonnées sont pré-calculés à partir d'un contour
 * géographique simplifié du Canada, projeté en conique (les longitudes se
 * resserrent vers le nord). Repère du SVG : 1000 × 620.
 *
 * Terre-Neuve est rattachée au continent dans le contour : approximation
 * assumée, la carte est décorative et non cartographique.
 */
import { deliveryCities } from '#shared/config/cities'

export interface DeliveryCity {
  id: string
  name: string
  region: string
  /** Coordonnées dans le repère du SVG. */
  x: number
  y: number
  delay: string
}

export const MAP_WIDTH = 1000
export const MAP_HEIGHT = 620

/**
 * Ce que la carte ajoute aux villes desservies : une position dans le SVG et
 * un délai annoncé. Les noms et les provinces, eux, ne sont pas recopiés — ils
 * viennent de `#shared/config/cities`, seule liste à tenir à jour.
 */
const MAP_POINTS: Record<string, { x: number, y: number, delay: string }> = {
  vancouver: { x: 89.1, y: 444.9, delay: '3 à 5 jours' },
  calgary: { x: 211.6, y: 410.6, delay: '2 à 4 jours' },
  edmonton: { x: 230.4, y: 362.3, delay: '2 à 4 jours' },
  saskatoon: { x: 304.7, y: 389.7, delay: '2 à 4 jours' },
  winnipeg: { x: 417.3, y: 432.9, delay: '2 à 3 jours' },
  toronto: { x: 664.2, y: 553.8, delay: '24 à 48 h' },
  ottawa: { x: 707.2, y: 519.6, delay: '24 à 48 h' },
  montreal: { x: 735.7, y: 518.0, delay: '24 h' },
  quebec: { x: 759.8, y: 492.7, delay: '1 à 2 jours' },
  halifax: { x: 877.8, y: 534.5, delay: '3 à 4 jours' },
  'st-johns': { x: 996.8, y: 478.2, delay: '4 à 6 jours' },
  yellowknife: { x: 267.1, y: 190.0, delay: '5 à 7 jours' },
}

/** Libellés courts : la carte manque de place pour « Colombie-Britannique ». */
const REGION_LABEL: Record<string, string> = {
  BC: 'C.-B.',
  AB: 'Alberta',
  SK: 'Saskatchewan',
  MB: 'Manitoba',
  ON: 'Ontario',
  QC: 'Québec',
  NS: 'Nouvelle-Écosse',
  NL: 'Terre-Neuve',
  NT: 'T. N.-O.',
}

/* Une ville sans point sur la carte est simplement absente du tracé : elle
   reste livrée, elle n'est pas dessinée. */
export const deliveryCitiesMap: DeliveryCity[] = deliveryCities.flatMap((city) => {
  const point = MAP_POINTS[city.id]
  if (!point) return []

  return [{
    id: city.id,
    name: city.name,
    region: REGION_LABEL[city.province] ?? city.province,
    ...point,
  }]
})

